def changed_paths(before, after):
    """Return sorted dot-separated paths of additions, removals, or unequal leaves.

    Recurses only where both values are dicts. Lists and other values are
    compared atomically. If a whole key is added or removed, only that
    parent path is reported.
    """
    paths = set()
    _diff(before, after, "", paths)
    return sorted(paths)


def _diff(before, after, prefix, paths):
    for key in set(before) | set(after):
        path = f"{prefix}.{key}" if prefix else key
        if key not in before:
            paths.add(path)
        elif key not in after:
            paths.add(path)
        else:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _diff(b_val, a_val, path, paths)
            elif b_val != a_val:
                paths.add(path)
