import copy


def merge(base: dict, overlay: dict) -> dict:
    """Recursively merge two dictionaries into a deep-independent result.

    - Overlay values replace base values (including lists and None).
    - A None overlay value does NOT delete a key; it sets the key to None.
    - Nested dicts are merged recursively; all other types are replaced.
    - Neither input is mutated, and the result shares no references with either input.
    """
    result: dict = {}

    for key in base:
        if key in overlay:
            base_val = base[key]
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = copy.deepcopy(overlay_val)
        else:
            result[key] = copy.deepcopy(base[key])

    for key in overlay:
        if key not in base:
            result[key] = copy.deepcopy(overlay[key])

    return result
