def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Collapses repeated slashes.
    - Removes '.' components.
    - Resolves '..' without going above root.
    - Returns '/' for root; no trailing slash otherwise.

    Raises:
        ValueError: If the path is not absolute (does not start with '/').
    """
    if not path.startswith('/'):
        raise ValueError(f"Path is not absolute: {path!r}")

    parts = path.split('/')
    stack: list[str] = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # else: ignore, cannot go above root
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
```

