def pack(items, max_bytes):
    """Greedily pack consecutive items into groups whose UTF-8 byte sum <= max_bytes."""
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    for item in items:
        if len(item.encode("utf-8")) > max_bytes:
            raise ValueError("item does not fit within max_bytes")

    if not items:
        return []

    result = []
    current = []
    current_size = 0

    for item in items:
        item_size = len(item.encode("utf-8"))
        if current and current_size + item_size > max_bytes:
            result.append(current)
            current = []
            current_size = 0
        current.append(item)
        current_size += item_size

    if current:
        result.append(current)

    return result
