def redact(value, sensitive):
    sensitive_lower = {s.lower() for s in sensitive}

    if isinstance(value, dict):
        result = {}
        for key, val in value.items():
            if isinstance(key, str) and key.lower() in sensitive_lower:
                result[key] = "[REDACTED]"
            else:
                result[key] = redact(val, sensitive)
        return result
    elif isinstance(value, list):
        return [redact(item, sensitive) for item in value]
    else:
        return value
```

